    # Black squares: (r, c) such that (r + c) % 2 == 0
    # Note: using 0-indexed (r, c)
    # A square is black if (r + c) % 2 == 0
    black_squares = []
    for r in range(n):
        for c in range(m):
            if (r + c) % 2 == 0:
                black_squares.append((r, c))

    # Queen attack:
    # (r1, c1) and (r2, c2) attack if:
    # r1 == r2 or c1 == c2 or abs(r1-r2) == abs(c1-c2)

    # We want the maximum independent set of the queen-attack graph on black squares.
    # Since we need to find the max, and the board is small, we can use backtracking.

    def is_safe(sq, queens):
        r1, c1 = sq
        for r2, c2 in queens:
